-- Generated by scripts/build_compiled.py from src/fraudrules/rules/instant-payment/ip-002-instant-fan-in.yaml. Do not edit.
-- IP-002 Young account receives instant credits from many senders in a day
SELECT 'IP-002' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 86400
WHERE (a.direction = 'in' AND a.channel IN ('rtp', 'fednow', 'p2p') AND a.ts < (a.account_opened_ts + 5184000)) AND (b.direction = 'in' AND b.channel IN ('rtp', 'fednow', 'p2p') AND b.txn_type <> 'return')
GROUP BY a.id
HAVING (COUNT(DISTINCT b.counterparty_id) >= 5 AND SUM(b.amount_cents) >= 250000);
